$volumeGrades=[];foreach($volumeClasses as$vc)if(preg_match('/^(\d+)/u',$vc,$m))$volumeGrades[]=$m[1];$volumeGrades=array_values(array_unique($volumeGrades));sort($volumeGrades,SORT_NATURAL);
