$volumeRows=array_values(array_filter($assignments,function($a)use($volumeScope,$volumeTarget){$class=(string)($a['class']??'');if($volumeScope==='school')return true;return$volumeScope==='class'?$class===$volumeTarget:(bool)preg_match('/^'.preg_quote($volumeTarget,'/').'\D/u',$class);}));
$gradeRows=[];if($volumeScope==='grade')foreach($volumeRows as$a){$subject=(string)$a['subject'];if(!isset($gradeRows[$subject]))$gradeRows[$subject]=['subject'=>$subject,'periods'=>(float)$a['periods'],'base_periods'=>(float)($a['base_periods']??$a['periods']),'classes'=>[],'teachers'=>[]];$gradeRows[$subject]['classes'][]=(string)$a['class'];$gradeRows[$subject]['teachers'][]=(string)$a['teacher'];}
