?><section class="card overflow-hidden mb-3"><div class="p-3 border-bottom"><div class="d-flex justify-content-between align-items-start gap-3 flex-wrap"><div><h5 class="mb-1">Số tiết học của tuần</h5><small class="text-muted">Mặc định xem toàn trường. Chỉnh theo khối sẽ áp dụng cùng số tiết xuống tất cả lớp trong khối.</small></div><form method="get" class="d-flex gap-2"><input type="hidden" name="tab" value="data"><select class="form-select" name="scope" onchange="this.form.submit()"><option value="school" <?=$volumeScope==='school'?'selected':''?>>Toàn trường</option><option value="grade" <?=$volumeScope==='grade'?'selected':''?>>Sửa theo khối</option><option value="class" <?=$volumeScope==='class'?'selected':''?>>Sửa theo lớp</option></select><?php if($volumeScope!=='school'):?><select class="form-select" name="target" onchange="this.form.submit()"><?php foreach($volumeOptions as$option):?><option value="<?=e($option)?>" <?=$volumeTarget===$option?'selected':''?>><?=e($volumeScope==='grade'?'Khối '.$option:$option)?></option><?php endforeach;?></select><?php endif;?></form></div><div class="mt-3 d-flex gap-2 flex-wrap"><span class="badge text-bg-primary fs-6">Tổng <?=e(rtrim(rtrim(number_format($volumeTotal,1,'.',''),'0'),'.'))?> tiết/tuần</span><span class="badge text-bg-light border fs-6"><?=count($volumeRows)?> phân công</span></div></div>
