<?php if($volumeScope==='grade'):foreach($gradeRows as$subject=>$a):$key=substr(hash('sha256',$subject),0,16);?><tr><td><strong><?=e($subject)?></strong></td><td><?=e(count(array_unique($a['classes'])))?> lớp · <?=e(count(array_unique($a['teachers'])))?> GV</td><td><input type="hidden" name="grade_subject[<?=$key?>]" value="<?=e($subject)?>"><input class="form-control form-control-sm" type="number" min="0" max="30" step="0.5" name="grade_periods[<?=$key?>]" value="<?=e($a['periods'])?>"></td><td><?=e($a['base_periods'])?></td></tr><?php endforeach;else:foreach($volumeRows as$a):?><tr><td><strong><?=e($a['class'])?></strong></td><td><?=e($a['subject'])?></td><td><?=e($a['teacher'])?></td><td><input class="form-control form-control-sm" type="number" min="0" max="30" step="0.5" name="periods[<?=e($a['id'])?>]" value="<?=e($a['periods'])?>" <?=$volumeScope==='school'?'readonly':''?>></td><td><?=e($a['base_periods']??$a['periods'])?></td></tr><?php endforeach;endif;if(!$volumeRows):?><tr><td colspan="5" class="text-center text-muted p-4">Không có môn học trong phạm vi đã chọn.</td></tr><?php endif;?></tbody></table></div>
