<?php elseif($tab==='guide'):?><style>.guide-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.guide-step{border:1px solid #d8e3e9;border-radius:14px;padding:16px;background:#fbfdfe}.guide-step h5{color:#245d7a}.guide-step ol,.guide-step ul{margin-bottom:0;padding-left:1.2rem}.guide-step li{margin:.38rem 0}.guide-note{border-left:4px solid #739aac;background:#eef5f7;padding:10px 12px;border-radius:8px}.guide-key{display:inline-block;border:1px solid #becbd2;background:#fff;border-radius:5px;padding:1px 6px;font-size:.82rem;box-shadow:0 1px 0 #aebbc2}@media(max-width:800px){.guide-grid{grid-template-columns:1fr}}</style><section class="card p-4"><div class="d-flex justify-content-between align-items-start flex-wrap gap-2"><div><h4><i class="bi bi-journal-text"></i> Hướng dẫn chi tiết xếp thời khóa biểu</h4><p class="text-muted">Làm theo thứ tự từ bước 1 đến bước 5. Dữ liệu nháp không ảnh hưởng TKB chính cho tới khi Công bố.</p></div><span class="badge text-bg-light border fs-6"><?=e($data['_workspace']['name']??'Phiên bản tuần')?></span></div><div class="guide-note mb-3"><strong>Nguyên tắc an toàn:</strong> chọn đúng phiên bản tuần, lưu sau mỗi nhóm thay đổi và chỉ Công bố khi số tiết chưa sắp, lớp trống và xung đột đều bằng 0.</div><div class="guide-grid">
<article class="guide-step"><h5>1. Phương án – tạo tuần làm việc</h5><ol><li>Chọn <strong>Tạo phiên bản tuần</strong>, nhập tên và tuần áp dụng.</li><li>Có thể sao chép tuần trước để giữ khối lượng và ràng buộc.</li><li>Kiểm tra tên phiên bản đang hiện trên thanh tiêu đề trước khi chỉnh.</li><li>Mỗi tuần là một vùng dữ liệu riêng; tạo lại phương án không đổi sang tuần khác.</li></ol></article>
<article class="guide-step"><h5>2. Khối lượng – khai báo số tiết</h5><ol><li><strong>Toàn trường</strong> dùng để kiểm tra tổng thể và tổng số tiết/tuần.</li><li>Chọn <strong>Khối</strong>, sửa một môn rồi Lưu: số tiết đó áp dụng xuống mọi lớp trong khối.</li><li>Chọn <strong>Lớp</strong> khi một lớp cần số tiết khác với khối.</li><li>Đối chiếu cột PCCM gốc; giá trị 0 nghĩa là môn không xếp trong tuần này.</li></ol></article>
<article class="guide-step"><h5>3. Ràng buộc – khóa những ô không được xếp</h5><ul><li><strong>GV/lớp bận:</strong> chọn đúng loại và đối tượng, chấm các ô bận rồi bấm Lưu bảng bận.</li><li><strong>Ngày, buổi học:</strong> chọn Toàn trường, Khối hoặc Lớp; chấm ô không học rồi Lưu.</li><li><strong>Môn học:</strong> giới hạn chỉ học Sáng/Chiều hoặc một khoảng tiết.</li><li><strong>Tiết giảng:</strong> đặt tiết đôi hoặc cố định môn vào ngày, buổi, tiết.</li><li>Mở tab <strong>Đang áp dụng</strong> để rà lại toàn bộ ràng buộc đã lưu.</li></ul></article>
<article class="guide-step"><h5>4. Xếp TKB lần đầu hoặc xếp lại</h5><ol><li>Bấm <strong>Xếp TKB lần đầu</strong> tại trang Xem & chỉnh.</li><li>Theo dõi thanh tiến độ; không đóng trang khi bộ xếp đang chạy.</li><li>Khi xếp lại, các thẻ có nhãn <i class="bi bi-lock-fill"></i> <strong>Khóa</strong> được giữ nguyên.</li><li>Mở <strong>Chẩn đoán</strong> nếu còn tiết chưa sắp hoặc xung đột.</li><li>Bộ xếp ưu tiên lấp kín tiết sáng trước, sau đó mới dùng buổi chiều.</li></ol></article>
<article class="guide-step"><h5>5. Xem & chỉnh – kéo thả thẻ</h5><ul><li>Chọn <strong>Lớp ↔ GV</strong> để xem một lớp; <strong>GV ↔ Lớp</strong> để xem một giáo viên.</li><li>Giữ chuột trái trên thẻ, kéo sang ô trống để chuyển tiết.</li><li>Kéo vào ô có thẻ để đổi chỗ nếu hai tiết đều hợp lệ.</li><li>Màu xanh nhạt: chuyển được; vàng nhạt: đổi chỗ; đỏ nhạt: không hợp lệ.</li><li>Sau mỗi lần chỉnh, lớp/GV đang chọn được giữ nguyên.</li></ul></article>
<article class="guide-step"><h5>Chuột phải – khóa, thêm hoặc xóa tiết</h5><ul><li>Nhấp chuột phải vào một thẻ để mở menu thao tác.</li><li>Chọn <strong>Khóa tiết</strong> để giữ vị trí khi xếp lại; thẻ sẽ hiện nhãn ổ khóa.</li><li>Chọn <strong>Mở khóa</strong> trước khi muốn kéo một tiết đã khóa.</li><li>Dùng <strong>Xóa tiết</strong> khi cần đưa tiết ra khỏi bảng; có thể thêm lại từ danh sách Tiết chưa sắp.</li><li>Nhấn <span class="guide-key">Esc</span> hoặc bấm ra ngoài để đóng menu.</li></ul></article>
<article class="guide-step"><h5>Kiểm tra trước khi công bố</h5><ul><li>Tiết chưa sắp = 0.</li><li>Lớp trống = 0 và Xung đột = 0.</li><li>Kiểm tra các lớp, giáo viên, tiết khóa và buổi học đặc biệt.</li><li>Nếu chưa đạt, quay lại Xem & chỉnh hoặc Ràng buộc rồi xếp lại.</li></ul></article>
<article class="guide-step"><h5>5. Công bố – đưa vào TKB chính</h5><ol><li>Mở tab Công bố và chọn đúng tuần áp dụng.</li><li>Đọc cảnh báo ghi đè nếu tuần đó đã có TKB.</li><li>Xác nhận Công bố. Chỉ bước này mới thay đổi TKB chính.</li><li>Sau công bố, mở <strong>Xem TKB chính</strong> để kiểm tra kết quả.</li></ol></article>
</div></section>
<?php elseif($tab==='constraints'):?><div class="row g-3"><div class="col-lg-5"><section class="card p-3"><h5>Khung tuần và tiêu chí tối ưu</h5><form method="post" class="row g-3"><input type="hidden" name="csrf" value="<?=e($csrf)?>"><input type="hidden" name="action" value="settings"><input type="hidden" name="return_tab" value="constraints"><div class="col-12"><?php for($d=2;$d<=7;$d++):?><label class="me-3"><input type="checkbox" name="days[]" value="<?=$d?>" <?=in_array($d,$data['settings']['days'])?'checked':''?>> Thứ <?=$d?></label><?php endfor;?></div><div class="col-6"><label>Tiết sáng</label><input class="form-control" type="number" name="morning_periods" value="<?=e($data['settings']['morning_periods'])?>"></div><div class="col-6"><label>Tiết chiều</label><input class="form-control" type="number" name="afternoon_periods" value="<?=e($data['settings']['afternoon_periods'])?>"></div><div class="col-6"><label>Lượt tối ưu</label><input class="form-control" type="number" name="attempts" value="<?=e($data['settings']['attempts'])?>"></div><div class="col-6"><label>Thời gian chạy tối đa (giây)</label><input class="form-control" type="number" name="run_seconds" min="3" max="30" value="<?=e($data['settings']['run_seconds'])?>"></div><div class="col-6"><label>Tối đa tiết GV/ngày</label><input class="form-control" type="number" name="max_teacher_daily" value="<?=e($data['settings']['max_teacher_daily'])?>"></div><div class="col-6"><label>Tiết trống GV mong muốn tối đa</label><input class="form-control" type="number" name="max_teacher_gaps" value="<?=e($data['settings']['max_teacher_gaps'])?>"></div><div class="col-12"><label class="d-block"><input type="checkbox" name="avoid_edges" value="1" <?=!empty($data['settings']['avoid_edges'])?'checked':''?>> Hạn chế tiết đầu/cuối</label><label><input type="checkbox" name="optimize_teacher_days" value="1" <?=!empty($data['settings']['optimize_teacher_days'])?'checked':''?>> Gom lịch để giảm số ngày giáo viên phải đến trường</label></div><div><button class="btn btn-primary">Lưu cấu hình</button></div></form></section></div><div class="col-lg-7"><section class="card p-3"><h5>Thời gian giáo viên không thể dạy</h5><form method="post" class="row g-2 mb-3"><input type="hidden" name="csrf" value="<?=e($csrf)?>"><input type="hidden" name="action" value="blocked_save"><input type="hidden" name="return_tab" value="constraints"><div class="col-md-5"><select class="form-select" name="teacher" required><option value="">Chọn GV</option><?php foreach($teachers as$t):?><option><?=e($t)?></option><?php endforeach;?></select></div><div class="col-md-2"><select class="form-select" name="day"><?php foreach($data['settings']['days']as$d):?><option value="<?=$d?>">T<?=$d?></option><?php endforeach;?></select></div><div class="col-md-2"><select class="form-select" name="session"><option>Sáng</option><option>Chiều</option></select></div><div class="col-md-1"><input class="form-control" name="period" type="number" value="1"></div><div class="col-md-2"><button class="btn btn-outline-primary w-100">Thêm</button></div></form><?php foreach($data['blocked']as$key=>$b):?><div class="d-flex justify-content-between border-top py-2"><span><strong><?=e($b['teacher'])?></strong> · T<?=e($b['day'])?> · <?=e($b['session'])?> <?=e($b['period'])?></span><form method="post"><input type="hidden" name="csrf" value="<?=e($csrf)?>"><input type="hidden" name="action" value="blocked_delete"><input type="hidden" name="key" value="<?=e($key)?>"><button class="btn btn-sm btn-outline-danger">×</button></form></div><?php endforeach;if(!$data['blocked']):?><div class="text-muted">Chưa khai báo thời gian bận.</div><?php endif;?></section></div></div>
