$a['period']]<=>[$b['day'],$b['session'],$b['period']]);foreach($sorted as$e):?><tr class="<?=count($e['classes'])>1?'table-success':''?>"><td>T<?=e($e['day'])?></td><td><?=e($e['session'])?> · <strong><?=e($e['period'])?></strong></td><td><?=e($e['subject'])?></td><td><?=e(implode(' + ',$e['classes']))?></td><td><?=e($e['teacher'])?></td><td><div class="d-flex gap-1"><form method="post"><input type="hidden" name="csrf" value="<?=e($csrf)?>"><input type="hidden" name="action" value="lock"><input type="hidden" name="plan_id" value="<?=e($activePlan['id'])?>"><input type="hidden" name="activity_id" value="<?=e($e['activity_id'])?>"><button class="btn btn-sm <?=$e['locked']?'btn-warning':'btn-outline-secondary'?>"><i class="bi bi-lock"></i></button></form><form method="post" class="d-flex gap-1"><input type="hidden" name="csrf" value="<?=e($csrf)?>"><input type="hidden" name="action" value="move"><input type="hidden" name="return_tab" value="plan"><input type="hidden" name="plan_id" value="<?=e($activePlan['id'])?>"><input type="hidden" name="activity_id" value="<?=e($e['activity_id'])?>"><select class="form-select form-select-sm" name="day"><?php foreach($data['settings']['days']as$d):?><option value="<?=$d?>" <?=$d==$e['day']?'selected':''?>>T<?=$d?></option><?php endforeach;?></select><select class="form-select form-select-sm" name="session"><option <?=$e['session']==='Sáng'?'selected':''?>>Sáng</option><option <?=$e['session']==='Chiều'?'selected':''?>>Chiều</option></select><input class="form-control form-control-sm" style="width:60px" type="number" name="period" value="<?=e($e['period'])?>"><button class="btn btn-sm btn-outline-primary">Đổi</button></form></div></td></tr><?php endforeach;?></tbody></table></div></section></div><div class="col-lg-4"><section class="card p-3 h-100"><h6>Chẩn đoán điểm nghẽn</h6><?php foreach(['Lớp còn thiếu'=>$diag['missing_class'],'Môn còn thiếu'=>$diag['missing_subject'],'Giáo viên còn thiếu'=>$diag['missing_teacher'],'Nguyên nhân'=>$diag['bottlenecks']]as$label=>$rows):?><div class="fw-bold small mt-2"><?=e($label)?></div><?php if($rows):?><ul class="diag-list"><?php arsort($rows);foreach($rows as$name=>$count):?><li><?=e($name)?>: <strong><?=e($count)?></strong> tiết</li><?php endforeach;?></ul><?php else:?><div class="small text-success">Không có</div><?php endif;?><?php endforeach;?><?php if($diag['empty_classes']):?><div class="fw-bold small mt-2">Lớp chưa có tiết</div><div class="text-danger small"><?=e(implode(', ',$diag['empty_classes']))?></div><?php endif;?></section></div></div><?php $view=(string)($_GET['view']??'class');if(!in_array($view,['class','teacher','school'],true))$view='class';$viewClass=(string)($_GET['class']??($classes[0]??''));$viewTeacher=(string)($_GET['teacher']??($teachers?reset($teachers):''));?><section class="card p-3 mb-3"><div class="d-flex justify-content-between align-items-end flex-wrap gap-2"><div><h5 class="mb-0">Xem phương án như TKB chính</h5><small class="text-muted">Kiểm tra theo lớp, giáo viên hoặc toàn trường trước khi công bố.</small></div><form method="get" class="d-flex gap-2 flex-wrap"><input type="hidden" name="tab" value="plan"><select class="form-select form-select-sm" name="view" onchange="this.form.submit()"><option value="class" <?=$view==='class'?'selected':''?>>Theo lớp</option><option value="teacher" <?=$view==='teacher'?'selected':''?>>Theo giáo viên</option><option value="school" <?=$view==='school'?'selected':''?>>Toàn trường</option></select><?php if($view==='class'):?><select class="form-select form-select-sm" name="class" onchange="this.form.submit()"><?php foreach($classes as$c):?><option <?=$viewClass===$c?'selected':''?>><?=e($c)?></option><?php endforeach;?></select><?php elseif($view==='teacher'):?><select class="form-select form-select-sm" name="teacher" onchange="this.form.submit()"><?php foreach($teachers as$t):?><option <?=$viewTeacher===$t?'selected':''?>><?=e($t)?></option><?php endforeach;?></select><?php endif;?></form></div><?php if($view==='school'):foreach($classes as$c)ttb_preview_matrix(ttb_preview_entries($activePlan['entries'],'class',$c),'Lớp '.$c,$data['settings']);elseif($view==='teacher'):ttb_preview_matrix(ttb_preview_entries($activePlan['entries'],'teacher',$viewTeacher),'Giáo viên '.$viewTeacher,$data['settings']);else:ttb_preview_matrix(ttb_preview_entries($activePlan['entries'],'class',$viewClass),'Lớp '.$viewClass,$data['settings']);endif;?></section><form method="post" class="mt-2" onsubmit="return confirm('Xóa bản nháp?')"><input type="hidden" name="csrf" value="<?=e($csrf)?>"><input type="hidden" name="action" value="delete_plan"><input type="hidden" name="id" value="<?=e($activePlan['id'])?>"><button class="btn btn-outline-danger btn-sm">Xóa bản nháp</button></form><?php else:?><div class="alert alert-info">Chưa có phương án.</div><?php endif;?>
<?php elseif($tab==='publish'):?><section class="card p-4"><h4>Duyệt và công bố</h4><p class="text-muted">Tạo phiên bản mới; TKB cũ vẫn ở Lịch sử để khôi phục.</p><?php if(!$activePlan):?><div class="alert alert-warning">Chưa có phương án.</div><?php else:$valid=empty($activePlan['unplaced'])&&empty($activePlan['errors']);?><div class="alert <?=$valid?'alert-success':'alert-danger'?>"><?=$valid?'Phương án hợp lệ.':'Còn tiết chưa xếp hoặc xung đột.'?></div><form method="post" class="row g-3"><input type="hidden" name="csrf" value="<?=e($csrf)?>"><input type="hidden" name="action" value="publish"><input type="hidden" name="return_tab" value="publish"><input type="hidden" name="plan_id" value="<?=e($activePlan['id'])?>"><div class="col-md-4"><input class="form-control" name="name" value="TKB tự động <?=date('d-m-Y')?>"></div><div class="col-md-4"><input class="form-control" type="date" name="week_from" required></div><div class="col-md-4"><input class="form-control" type="date" name="week_to" required></div><div><button class="btn btn-success" <?=$valid?'':'disabled'?>>Công bố sang TKB chính</button></div></form><?php endif;?></section>
<?php else:?><section class="card p-4"><h4>Bật hoặc tắt ứng dụng</h4><p>Tắt ứng dụng không xóa PCCM, Sổ đầu bài hoặc TKB đã công bố.</p><form method="post"><input type="hidden" name="csrf" value="<?=e($csrf)?>"><input type="hidden" name="action" value="toggle"><label class="form-check form-switch fs-5"><input class="form-check-input" type="checkbox" name="enabled" value="1" <?=$data['enabled']?'checked':''?>> Cho phép xếp TKB</label><button class="btn btn-primary mt-3">Lưu</button></form></section><?php endif;?></main><div class="optimizer-overlay" id="optimizerOverlay"><div class="optimizer-panel text-center"><div class="optimizer-percent" id="optimizerPercent">0%</div><div class="progress optimizer-bar my-3"><div class="progress-bar progress-bar-striped progress-bar-animated" id="optimizerBar" style="width:0%"></div></div><div class="optimizer-status" id="optimizerStatus">Đang đọc PCCM và dựng ràng buộc…</div><small class="text-muted d-block mt-2">Không đóng trang trong khi hệ thống đang tạo phương án.</small></div></div><script>document.querySelectorAll('.optimizer-form').forEach(function(form){form.addEventListener('submit',function(){var overlay=document.getElementById('optimizerOverlay'),bar=document.getElementById('optimizerBar'),number=document.getElementById('optimizerPercent'),status=document.getElementById('optimizerStatus'),p=0;overlay.classList.add('show');var timer=setInterval(function(){if(p<70)p+=Math.max(1,Math.round((70-p)/7));else if(p<92)p+=1;if(p>92)p=92;bar.style.width=p+'%';number.textContent=p+'%';status.textContent=p<25?'Đang đọc PCCM và dựng ràng buộc…':(p<60?'Đang loại các khung giờ xung đột…':(p<88?'Đang thử và chấm điểm phương án…':'Đang hoàn tất kết quả…'));},180);window.addEventListener('pageshow',function(){clearInterval(timer);overlay.classList.remove('show');},{once:true});});});</script></body></html>
